begin;
alter table public.job_addon_catalog add column if not exists customer_visible boolean not null default false,add column if not exists image_url text,add column if not exists max_customer_quantity integer not null default 1 check(max_customer_quantity between 1 and 10000),add column if not exists inventory_item_id uuid references public.inventory_items(id) on delete restrict,add column if not exists compatibility_required boolean not null default false;
create table public.job_addon_applicable_inventory_items(addon_id uuid not null references public.job_addon_catalog(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete cascade,primary key(addon_id,inventory_item_id));
create table public.job_addon_compatible_inventory_items(addon_id uuid not null references public.job_addon_catalog(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete cascade,primary key(addon_id,inventory_item_id));
alter table public.job_addon_applicable_inventory_items enable row level security;alter table public.job_addon_compatible_inventory_items enable row level security;
create policy "members read addon applicability" on public.job_addon_applicable_inventory_items for select to authenticated using(public.is_business_member(business_id));create policy "managers manage addon applicability" on public.job_addon_applicable_inventory_items for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager'])) with check(public.has_business_role(business_id,array['owner','admin','manager']));create policy "members read addon compatibility" on public.job_addon_compatible_inventory_items for select to authenticated using(public.is_business_member(business_id));create policy "managers manage addon compatibility" on public.job_addon_compatible_inventory_items for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager'])) with check(public.has_business_role(business_id,array['owner','admin','manager']));
commit;
